THOUGHT: I’ll create the bootable foundation now: the required supervisor, dependencies, SQLite schema, authentication/workspaces/channels/messages APIs, and a minimal SPA endpoint. This gives the staged checks something runnable and establishes the shared database/event model.

```mswea_bash_command
cat > /app/requirements.txt <<'EOF'
aiohttp==3.10.10
tzdata==2024.2
EOF
cat > /app/start.sh <<'EOF'
#!/bin/bash
cd /app
mkdir -p /app/data/files
python3 /app/core.py --init-db
(while true; do redis-server --port 6379 --bind 127.0.0.1 --save '' --appendonly no; sleep 1; done) &
for n in 0 1 2; do (while true; do python3 /app/server.py --node $n; sleep 1; done) & done
(while true; do [ -f /app/irc.py ] && python3 /app/irc.py; sleep 1; done) &
wait
EOF
chmod +x /app/start.sh
cat > /app/core.py <<'PY'
import sqlite3,os,sys,secrets,hashlib,base64,json,re,datetime
DB='/app/data/huddle.db'
def connect():
 c=sqlite3.connect(DB,timeout=10,isolation_level=None); c.row_factory=sqlite3.Row;c.execute('PRAGMA busy_timeout=10000');return c
def now(): return datetime.datetime.now(datetime.timezone.utc).isoformat().replace('+00:00','Z')
def init_db():
 os.makedirs('/app/data',exist_ok=True); c=connect();c.execute('PRAGMA journal_mode=WAL')
 c.executescript('''CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,username TEXT UNIQUE,password TEXT,display_name TEXT,timezone TEXT DEFAULT "UTC",avatar_url TEXT DEFAULT "",status_text TEXT DEFAULT "",status_emoji TEXT DEFAULT "");
 CREATE TABLE IF NOT EXISTS tokens(token TEXT PRIMARY KEY,user_id INTEGER);
 CREATE TABLE IF NOT EXISTS workspaces(id INTEGER PRIMARY KEY,slug TEXT UNIQUE,name TEXT,owner_id INTEGER,join_mode TEXT DEFAULT "open");
 CREATE TABLE IF NOT EXISTS members(workspace_id INTEGER,user_id INTEGER,role TEXT,PRIMARY KEY(workspace_id,user_id));
 CREATE TABLE IF NOT EXISTS channels(id INTEGER PRIMARY KEY,workspace_id INTEGER,name TEXT,is_private INTEGER DEFAULT 0,is_dm INTEGER DEFAULT 0,topic TEXT DEFAULT "",is_archived INTEGER DEFAULT 0,last_event_id INTEGER DEFAULT 0);
 CREATE TABLE IF NOT EXISTS channel_members(channel_id INTEGER,user_id INTEGER,PRIMARY KEY(channel_id,user_id));
 CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY,channel_id INTEGER,author_id INTEGER,body TEXT,parent_id INTEGER,created_at TEXT,edited_at TEXT,deleted INTEGER DEFAULT 0);
 CREATE TABLE IF NOT EXISTS events(channel_id INTEGER,event_id INTEGER,payload TEXT,PRIMARY KEY(channel_id,event_id));
 CREATE TABLE IF NOT EXISTS reactions(message_id INTEGER,user_id INTEGER,emoji TEXT,created_at TEXT,PRIMARY KEY(message_id,user_id,emoji));''')
 c.close()
def pw(p): return hashlib.sha256(p.encode()).hexdigest()
def user_json(r): return {k:r[k] for k in ['id','username','display_name','timezone','avatar_url','status_text','status_emoji']}
def chan_json(r): return {**dict(r),'is_private':bool(r['is_private']),'is_dm':bool(r['is_dm']),'is_archived':bool(r['is_archived'])}
def token_user(t):
 c=connect();r=c.execute('SELECT u.* FROM users u JOIN tokens t ON t.user_id=u.id WHERE t.token=?',(t,)).fetchone();c.close();return r
def emit(c,ch,kind,payload):
 c.execute('UPDATE channels SET last_event_id=last_event_id+1 WHERE id=?',(ch,)); n=c.execute('SELECT last_event_id FROM channels WHERE id=?',(ch,)).fetchone()[0]
 frame={'type':kind,'event_id':n,'channel_id':ch,**payload};c.execute('INSERT INTO events VALUES(?,?,?)',(ch,n,json.dumps(frame)));return frame
def msg_json(r):
 c=connect(); rr=c.execute('SELECT emoji,COUNT(*) n,GROUP_CONCAT(user_id) ids FROM reactions WHERE message_id=? GROUP BY emoji ORDER BY MIN(created_at)',(r['id'],)).fetchall();c.close()
 d=dict(r);d['author']=user_json(token_user(next(iter([]),'') ) ) if False else None;d['parent_id']=d['parent_id'];d['reply_count']=0;d['files']=[];d['mentions']=[];d['reactions']=[{'emoji':x['emoji'],'count':x['n'],'user_ids':[int(i) for i in x['ids'].split(',')]} for x in rr];return d
if __name__=='__main__': init_db()
PY
cat > /app/server.py <<'PY'
from aiohttp import web,WSMsgType
import argparse,json,re,secrets,base64,sqlite3,sys
import core
def out(x,status=200): return web.json_response(x,status=status)
async def body(r):
 try:return await r.json()
 except:return None
def auth(r):
 h=r.headers.get('Authorization','');return core.token_user(h[7:] if h.startswith('Bearer ') else '')
async def reg(r):
 b=await body(r)
 if not isinstance(b,dict) or not re.fullmatch(r'[A-Za-z0-9_]+',str(b.get('username',''))) or len(str(b.get('password','')))<8:return out({'error':'invalid'},400)
 c=core.connect()
 try:
  c.execute('INSERT INTO users(username,password,display_name) VALUES(?,?,?)',(b['username'],core.pw(b['password']),b.get('display_name') or b['username']))
 except sqlite3.IntegrityError:return out({'error':'duplicate'},409)
 u=c.execute('SELECT * FROM users WHERE id=last_insert_rowid()').fetchone();t=secrets.token_urlsafe(24);c.execute('INSERT INTO tokens VALUES(?,?)',(t,u['id']));c.close();return out({'user':core.user_json(u),'token':t},201)
async def login(r):
 b=await body(r);c=core.connect();u=c.execute('SELECT * FROM users WHERE username=? AND password=?',(b.get('username') if isinstance(b,dict) else '',core.pw(b.get('password','')) if isinstance(b,dict) else '')).fetchone()
 if not u:return out({'error':'unauthorized'},401)
 t=secrets.token_urlsafe(24);c.execute('INSERT INTO tokens VALUES(?,?)',(t,u['id']));return out({'user':core.user_json(u),'token':t})
async def me(r):
 u=auth(r);return out({'user':core.user_json(u)}) if u else out({'error':'unauthorized'},401)
async def health(r): return out({'status':'ok','node_id':r.app['node']})
async def workspaces(r):
 u=auth(r)
 if not u:return out({'error':'unauthorized'},401)
 c=core.connect(); rows=c.execute('SELECT w.* FROM workspaces w JOIN members m ON m.workspace_id=w.id WHERE m.user_id=?',(u['id'],)).fetchall();return out({'workspaces':[dict(x) for x in rows]})
async def create_ws(r):
 u=auth(r);b=await body(r)
 if not u:return out({'error':'unauthorized'},401)
 c=core.connect()
 try:c.execute('INSERT INTO workspaces(slug,name,owner_id) VALUES(?,?,?)',(b['slug'],b['name'],u['id']))
 except:return out({'error':'duplicate'},409)
 w=c.execute('SELECT * FROM workspaces WHERE id=last_insert_rowid()').fetchone();c.execute('INSERT INTO members VALUES(?,?,?)',(w['id'],u['id'],'owner'));c.execute('INSERT INTO channels(workspace_id,name) VALUES(?,?)',(w['id'],'general'));ch=c.execute('SELECT * FROM channels WHERE id=last_insert_rowid()').fetchone();c.execute('INSERT INTO channel_members VALUES(?,?)',(ch['id'],u['id']));return out({'workspace':dict(w),'general_channel':core.chan_json(ch)},201)
async def ws_detail(r):
 u=auth(r);c=core.connect();w=c.execute('SELECT * FROM workspaces WHERE slug=?',(r.match_info['slug'],)).fetchone()
 if not u:return out({'error':'unauthorized'},401)
 if not w:return out({'error':'not found'},404)
 cs=c.execute('SELECT * FROM channels WHERE workspace_id=?',(w['id'],)).fetchall();return out({'workspace':dict(w),'channels':[core.chan_json(x) for x in cs]})
async def create_channel(r):
 u=auth(r);b=await body(r);c=core.connect();w=c.execute('SELECT * FROM workspaces WHERE slug=?',(r.match_info['slug'],)).fetchone()
 if not u:return out({'error':'unauthorized'},401)
 if not w:return out({'error':'not found'},404)
 c.execute('INSERT INTO channels(workspace_id,name,is_private,topic) VALUES(?,?,?,?)',(w['id'],b.get('name'),int(bool(b.get('is_private'))),b.get('topic','')));ch=c.execute('SELECT * FROM channels WHERE id=last_insert_rowid()').fetchone();c.execute('INSERT OR IGNORE INTO channel_members VALUES(?,?)',(ch['id'],u['id']));return out({'channel':core.chan_json(ch)},201)
async def messages(r):
 u=auth(r);c=core.connect();ch=c.execute('SELECT * FROM channels WHERE id=?',(r.match_info['id'],)).fetchone()
 if not u:return out({'error':'unauthorized'},401)
 if not ch:return out({'error':'not found'},404)
 if r.method=='POST':
  b=await body(r)
  if not isinstance(b,dict) or not isinstance(b.get('body'),str) or not b['body'].strip():return out({'error':'invalid'},400)
  c.execute('INSERT INTO messages(channel_id,author_id,body,created_at) VALUES(?,?,?,?)',(ch['id'],u['id'],b['body'],core.now()));m=c.execute('SELECT * FROM messages WHERE id=last_insert_rowid()').fetchone();core.emit(c,ch['id'],'message.created',{'message':dict(m)});return out({'message':core.msg_json(m)},201)
 ms=c.execute('SELECT * FROM messages WHERE channel_id=? AND deleted=0 ORDER BY id DESC',(ch['id'],)).fetchall();return out({'messages':[core.msg_json(x) for x in ms],'next_cursor':None})
async def wsock(r):
 u=auth(r)
 if not u:return out({'error':'unauthorized'},401)
 w=web.WebSocketResponse();await w.prepare(r);await w.send_json({'type':'ready'});async for x in w: pass
 return w
async def root(r): return web.FileResponse('/app/static/index.html')
app=web.Application();app['node']=0
for path,method,fn in [('/api/health','GET',health),('/api/auth/register','POST',reg),('/api/auth/login','POST',login),('/api/auth/me','GET',me),('/api/workspaces','GET',workspaces),('/api/workspaces','POST',create_ws),('/api/workspaces/{slug}','GET',ws_detail),('/api/workspaces/{slug}/channels','POST',create_channel),('/api/channels/{id}/messages','GET',messages),('/api/channels/{id}/messages','POST',messages),('/api/ws','GET',wsock),('/','GET',root)]:app.router.add_route(method,path,fn)
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--node',type=int,default=0);a=p.parse_args();app['node']=a.node;web.run_app(app,host='127.0.0.1',port=8000+a.node)
PY
mkdir -p /app/static
cat > /app/static/index.html <<'EOF'
<!doctype html><html><body><main id="app"><h1>Huddle</h1><form data-testid="auth-form"><input name="username"><input name="password" type="password"><button data-testid="auth-submit" data-button-role="primary">Login</button></form><button data-testid="logout-btn" data-button-role="danger">Logout</button><div data-testid="channel-list"></div><div data-testid="message-list"></div><input data-testid="message-input"><button data-testid="send-btn" data-button-role="primary">Send</button></main><script src="/app.js"></script></body></html>
EOF
cat > /app/static/app.js <<'EOF'
const state={token:localStorage.getItem('huddle.token')};async function api(p,o={}){o.headers={...(o.headers||{}),Authorization:'Bearer '+state.token,'Content-Type':'application/json'};return fetch('/api'+p,o).then(x=>x.json())}document.querySelector('[data-testid=auth-form]').onsubmit=async e=>{e.preventDefault();let f=e.target,b=await api('/auth/login',{method:'POST',body:JSON.stringify({username:f.username.value,password:f.password.value})});if(b.token){state.token=b.token;localStorage.setItem('huddle.token',b.token)}};document.querySelector('[data-testid=logout-btn]').onclick=()=>{localStorage.removeItem('huddle.token');location.reload()}
EOF
python3 -m py_compile /app/core.py /app/server.py
/app/start.sh >/tmp/huddle.log 2>&1 & echo $! > /tmp/huddle.pid
sleep 2
curl -s http://127.0.0.1:8000/api/health
```

